(1, 'index.php?option=com_content&view=category&id=8', 'index.php?option=com_content&view=category&id=8', 'Việc làm', '', '2026-08-18 16:22:34', '1c5bbaa4b5fad3aeff292dae508123ca', 1, 1, 1, '*', NULL, NULL, '2026-08-18 16:22:34', NULL, 0, 0, 1, ),
(2, 'index.php?option=com_content&view=article&id=1', 'index.php?option=com_content&view=article&id=1:tuy-n-d-ng-vi-c-lam&catid=2', 'Tuyển dụng việc làm', ' TUYỂN DỤNG VIỆC LÀM Trung tâm việc làm cung cấp các thông tin tuyển dụng mới nhất dành cho người lao động. Các vị trí tuyển dụng: * Nhân viên văn phòng * Nhân viên kinh doanh * Nhân viên bán hàng * Nhân viên kỹ thuật Yêu cầu: * Có trách nhiệm trong công việc. * Có tinh thần học hỏi. * Ưu tiên ứng viên có kinh nghiệm. Liên hệ: Trung tâm việc làm để biết thêm thông tin chi tiết. ', '2026-08-18 16:26:17', '020a21122135c554e418a3f238e44af0', 1, 1, 1, '*', '2026-08-18 16:26:17', NULL, '2026-08-18 16:26:17', NULL, 0, 0, 3, ),
(3, 'index.php?option=com_content&view=article&id=2', 'index.php?option=com_content&view=article&id=2:nhan-vien-van-phong&catid=2', 'Nhân viên văn phòng', ' Vị trí: Nhân viên văn phòng Mô tả công việc: * Thực hiện các công việc hành chính, văn phòng. * Quản lý hồ sơ và giấy tờ. * Nhập liệu và xử lý thông tin. * Hỗ trợ các công việc khác theo yêu cầu. Yêu cầu: * Tốt nghiệp THPT trở lên. * Sử dụng cơ bản Word, Excel. * Có trách nhiệm và chăm chỉ. * Giao tiếp tốt, làm việc nhóm tốt. Quyền lợi: * Môi trường làm việc thân thiện. * Được hướng dẫn khi bắt đầu công việc. * Thu nhập ổn định. ', '2026-08-18 16:39:38', '16e9717d8de6040adbb06c8c832bebfc', 1, 1, 1, '*', '2026-08-18 16:39:38', NULL, '2026-08-18 16:39:38', NULL, 0, 0, 3, ),
(4, 'index.php?option=com_content&view=article&id=3', 'index.php?option=com_content&view=article&id=3:nhan-vien-kinh-doanh&catid=2', 'Nhân viên kinh doanh', ' Vị trí: Nhân viên kinh doanh Mô tả công việc: * Tìm kiếm và tư vấn khách hàng. * Giới thiệu sản phẩm, dịch vụ. * Chăm sóc khách hàng. * Theo dõi và hỗ trợ khách hàng trong quá trình sử dụng dịch vụ. Yêu cầu: * Giao tiếp tốt. * Năng động, nhiệt tình. * Có tinh thần trách nhiệm. Quyền lợi: * Thu nhập ổn định. * Thưởng theo hiệu quả công việc. * Môi trường làm việc chuyên nghiệp. ', '2026-08-18 16:41:16', 'c3052710a9fce2c0b5f0b1413748eae8', 1, 1, 1, '*', '2026-08-18 16:41:16', NULL, '2026-08-18 16:41:16', NULL, 0, 0, 3, );
INSERT INTO `rjtgh_finder_links` (`link_id`, `url`, `route`, `title`, `description`, `indexdate`, `md5sum`, `published`, `state`, `access`, `language`, `publish_start_date`, `publish_end_date`, `start_date`, `end_date`, `list_price`, `sale_price`, `type_id`, `object`) VALUES
(5, 'index.php?option=com_content&view=article&id=4', 'index.php?option=com_content&view=article&id=4:nhan-vien-ban-hang&catid=2', 'Nhân viên bán hàng', ' Vị trí: Nhân viên bán hàng Mô tả công việc: * Tư vấn và hỗ trợ khách hàng. * Sắp xếp hàng hóa. * Kiểm tra và quản lý hàng hóa tại cửa hàng. * Thực hiện các công việc theo sự phân công. Yêu cầu: * Trung thực, chăm chỉ. * Giao tiếp lịch sự. * Có trách nhiệm trong công việc. ', '2026-08-18 16:42:07', '2df7f8d09d9ad4ecdb5228d772736268', 1, 1, 1, '*', '2026-08-18 16:42:07', NULL, '2026-08-18 16:42:07', NULL, 0, 0, 3, ),
(6, 'index.php?option=com_content&view=article&id=5', 'index.php?option=com_content&view=article&id=5:nhan-vien-ki-thu-t&catid=2', 'Nhân viên kĩ thuật', ' Vị trí: Nhân viên kỹ thuật Mô tả công việc: * Kiểm tra và xử lý các vấn đề kỹ thuật. * Hỗ trợ bảo trì thiết bị. * Cài đặt và kiểm tra hệ thống khi cần thiết. * Hỗ trợ khách hàng về các vấn đề kỹ thuật. Yêu cầu: * Có kiến thức cơ bản về kỹ thuật và công nghệ thông tin. * Có khả năng xử lý sự cố. * Cẩn thận và có trách nhiệm. ', '2026-08-18 16:42:46', '48b3629f5d2031b171380dc61aac4097', 1, 1, 1, '*', '2026-08-18 16:42:46', NULL, '2026-08-18 16:42:46', NULL, 0, 0, 3, ),
(7, 'index.php?option=com_content&view=article&id=6', 'index.php?option=com_content&view=article&id=6:gi-i-thieu&catid=2', 'Giới thiêu', ' GIỚI THIỆU TRUNG TÂM DỊCH VỤ VIỆC LÀM Trung tâm Dịch vụ việc làm là nơi cung cấp thông tin việc làm, hỗ trợ người lao động tìm kiếm việc làm và kết nối với doanh nghiệp có nhu cầu tuyển dụng. Website được xây dựng nhằm cung cấp thông tin tuyển dụng, việc làm và các nội dung hỗ trợ người lao động một cách thuận tiện. ', '2026-08-26 05:30:08', '62e56788ce50e1e1b0f93a6d97a15ce2', 1, 1, 1, '*', '2026-08-26 05:30:08', NULL, '2026-08-26 05:30:08', NULL, 0, 0, 3, );

