(1, 'com_content.category.8', '', '2026-08-18 16:22:34', 192, 556, 'a2c90979bbf146164c7428dabf87b4ca53156cb0', '{\"id\":8,\"asset_id\":100,\"parent_id\":1,\"lft\":11,\"rgt\":12,\"level\":1,\"path\":null,\"extension\":\"com_content\",\"title\":\"Vi\\u1ec7c l\\u00e0m\",\"alias\":\"vi-c-lam\",\"note\":\"\",\"description\":\"\",\"published\":\"1\",\"checked_out\":null,\"checked_out_time\":null,\"access\":1,\"params\":\"{\\\"category_layout\\\":\\\"\\\",\\\"image\\\":\\\"\\\",\\\"image_alt\\\":\\\"\\\"}\",\"metadesc\":\"\",\"metakey\":\"\",\"metadata\":\"{\\\"author\\\":\\\"\\\",\\\"robots\\\":\\\"\\\"}\",\"created_user_id\":192,\"created_time\":\"2026-08-18 16:22:34\",\"modified_user_id\":192,\"modified_time\":\"2026-08-18 16:22:34\",\"hits\":null,\"language\":\"*\",\"version\":null}', 0),
(2, 'com_content.article.1', '', '2026-08-18 16:26:17', 192, 2410, '1f6803d8abb044eac17a5a81afc321b6e8ee77bb', '{\"id\":1,\"asset_id\":101,\"title\":\"Tuy\\u1ec3n d\\u1ee5ng vi\\u1ec7c l\\u00e0m\",\"alias\":\"tuy-n-d-ng-vi-c-lam\",\"introtext\":\"<p>TUY\\u1ec2N D\\u1ee4NG VI\\u1ec6C L\\u00c0M<\\/p>\\r\\n<p>Trung t\\u00e2m vi\\u1ec7c l\\u00e0m cung c\\u1ea5p c\\u00e1c th\\u00f4ng tin tuy\\u1ec3n d\\u1ee5ng m\\u1edbi nh\\u1ea5t d\\u00e0nh cho ng\\u01b0\\u1eddi lao \\u0111\\u1ed9ng.<\\/p>\\r\\n<p>C\\u00e1c v\\u1ecb tr\\u00ed tuy\\u1ec3n d\\u1ee5ng:<\\/p>\\r\\n<p>* Nh\\u00e2n vi\\u00ean v\\u0103n ph\\u00f2ng<br>* Nh\\u00e2n vi\\u00ean kinh doanh<br>* Nh\\u00e2n vi\\u00ean b\\u00e1n h\\u00e0ng<br>* Nh\\u00e2n vi\\u00ean k\\u1ef9 thu\\u1eadt<\\/p>\\r\\n<p>Y\\u00eau c\\u1ea7u:<\\/p>\\r\\n<p>* C\\u00f3 tr\\u00e1ch nhi\\u1ec7m trong c\\u00f4ng vi\\u1ec7c.<br>* C\\u00f3 tinh th\\u1ea7n h\\u1ecdc h\\u1ecfi.<br>* \\u01afu ti\\u00ean \\u1ee9ng vi\\u00ean c\\u00f3 kinh nghi\\u1ec7m.<\\/p>\\r\\n<p>Li\\u00ean h\\u1ec7: Trung t\\u00e2m vi\\u1ec7c l\\u00e0m \\u0111\\u1ec3 bi\\u1ebft th\\u00eam th\\u00f4ng tin chi ti\\u1ebft.<\\/p>\",\"fulltext\":\"\",\"state\":\"1\",\"catid\":2,\"created\":\"2026-08-18 16:26:17\",\"created_by\":192,\"created_by_alias\":\"\",\"modified\":\"2026-08-18 16:26:17\",\"modified_by\":192,\"checked_out\":null,\"checked_out_time\":null,\"publish_up\":\"2026-08-18 16:26:17\",\"publish_down\":null,\"images\":\"{\\\"image_intro\\\":\\\"\\\",\\\"image_intro_alt\\\":\\\"\\\",\\\"float_intro\\\":\\\"\\\",\\\"image_intro_caption\\\":\\\"\\\",\\\"image_fulltext\\\":\\\"\\\",\\\"image_fulltext_alt\\\":\\\"\\\",\\\"float_fulltext\\\":\\\"\\\",\\\"image_fulltext_caption\\\":\\\"\\\"}\",\"urls\":\"{\\\"urla\\\":\\\"\\\",\\\"urlatext\\\":\\\"\\\",\\\"targeta\\\":\\\"\\\",\\\"urlb\\\":\\\"\\\",\\\"urlbtext\\\":\\\"\\\",\\\"targetb\\\":\\\"\\\",\\\"urlc\\\":\\\"\\\",\\\"urlctext\\\":\\\"\\\",\\\"targetc\\\":\\\"\\\"}\",\"attribs\":\"{\\\"article_layout\\\":\\\"\\\",\\\"show_