INSERT INTO `tu9j5_finder_links` (`link_id`, `url`, `route`, `title`, `description`, `indexdate`, `md5sum`, `published`, `state`, `access`, `language`, `publish_start_date`, `publish_end_date`, `start_date`, `end_date`, `list_price`, `sale_price`, `type_id`, `object`) VALUES
(11, 'index.php?option=com_content&view=article&id=2', 'index.php?option=com_content&view=article&id=2:thong-bao&catid=14', 'Thông báo', '', '2026-08-30 17:22:32', '48a2c8b5e5d5a98ad513005a57c57f59', 1, 1, 1, '*', '2026-08-30 17:20:49', NULL, '2026-08-30 17:20:49', NULL, 0, 0, 3, ),
(12, 'index.php?option=com_content&view=article&id=3', 'index.php?option=com_content&view=article&id=3:lien-h-trung-tam-gi-i-thi-u-vi-c-lam&catid=15', 'Liên hệ Trung tâm Giới thiệu Việc làm', '', '2026-08-30 17:24:26', '57b7418d4adbf8fef7087b987ae01569', 1, 1, 1, '*', '2026-08-30 17:24:26', NULL, '2026-08-30 17:24:26', NULL, 0, 0, 3, ),
(13, 'index.php?option=com_content&view=article&id=4', 'index.php?option=com_content&view=article&id=4:vi-c-lam-ph-thong&catid=8', 'Việc làm phổ thông', ' Việc làm phổ thông Trung tâm giới thiệu các vị trí việc làm phổ thông dành cho người lao động có nhu cầu tìm kiếm việc làm phù hợp. Các vị trí việc làm có thể bao gồm công nhân sản xuất, nhân viên đóng gói, phụ kho, lao động tại các cơ sở sản xuất và các công việc phù hợp khác. Người lao động có thể tìm hiểu thông tin tuyển dụng, yêu cầu công việc và liên hệ với Trung tâm để được hỗ trợ. ', '2026-08-30 17:28:08', '0678c762a8ef2b9bcfaa30b791f95c63', 1, 1, 1, '*', '2026-08-30 17:28:08', NULL, '2026-08-30 17:28:08', NULL, 0, 0, 3, ),
(14, 'index.php?option=com_content&view=article&id=5', 'index.php?option=com_content&view=article&id=5:vi-c-lam-van-phong&catid=8', 'Việc làm văn phòng', ' Việc làm văn phòng Trung tâm giới thiệu các vị trí việc làm văn phòng dành cho người lao động có nhu cầu tìm kiếm công việc phù hợp với chuyên môn và kinh nghiệm. Một số vị trí có thể bao gồm nhân viên hành chính, nhân viên văn phòng, nhân viên kinh doanh, chăm sóc khách hàng và các vị trí liên quan. Người lao động có thể tìm hiểu yêu cầu công việc và liên hệ với Trung tâm để được tư vấn, hỗ trợ. ', '2026-08-30 17:29:41', 'ca14143a44e75730d880266ea9b340bb', 1, 1, 1, '*', '2026-08-30 17:29:41', NULL, '2026-08-30 17:29:41', NULL, 0, 0, 3, );
INSERT INTO `tu9j5_finder_links` (`link_id`, `url`, `route`, `title`, `description`, `indexdate`, `md5sum`, `published`, `state`, `access`, `language`, `publish_start_date`, `publish_end_date`, `start_date`, `end_date`, `list_price`, `sale_price`, `type_id`, `object`) VALUES
(15, 'index.php?option=com_content&view=article&id=6', 'index.php?option=com_content&view=article&id=6:vi-c-lam-k-thu-t&catid=8', 'Việc làm kỹ thuật', ' Việc làm kỹ thuật Trung tâm giới thiệu các vị trí việc làm thuộc nhóm kỹ thuật dành cho người lao động có chuyên môn và kinh nghiệm phù hợp. Các vị trí có thể bao gồm kỹ thuật viên, nhân viên kỹ thuật, cơ khí, điện, điện tử, vận hành và bảo trì máy móc. Người lao động có thể tìm hiểu thông tin tuyển dụng, yêu cầu công việc và liên hệ với Trung tâm để được tư vấn, hỗ trợ. ', '2026-08-30 17:31:39', 'e0fba64d89a98bcc7d6431f11684dd16', 1, 1, 1, '*', '2026-08-30 17:31:39', NULL, '2026-08-30 17:31:39', NULL, 0, 0, 3, ),
(16, 'index.php?option=com_content&view=article&id=7', 'index.php?option=com_content&view=article&id=7:vi-c-lam-ban-th-i-gian&catid=8', 'Việc làm bán thời gian', ' Việc làm bán thời gian Trung tâm giới thiệu các vị trí việc làm bán thời gian dành cho sinh viên, người lao động có nhu cầu làm việc theo thời gian linh hoạt. Các công việc có thể bao gồm nhân viên bán hàng, phục vụ, cộng tác viên, chăm sóc khách hàng và các vị trí phù hợp khác. Người tìm việc có thể lựa chọn công việc phù hợp với thời gian, khả năng và nhu cầu của mình. Vui lòng liên hệ với Trung tâm để được tư vấn và hỗ trợ. ', '2026-08-30 17:32:24', '8d558590adc401016bd843bd99aaba50', 1, 1, 1, '*', '2026-08-30 17:32:24', NULL, '2026-08-30 17:32:24', NULL, 0, 0, 3, ),
(17, 'index.php?option=com_content&view=article&id=8', 'index.php?option=com_content&view=article&id=8:thong-bao-tuy-n-d-ng-m-i-nh-t&catid=9', 'Thông báo tuyển dụng mới nhất', ' Trung tâm Giới thiệu Việc làm cập nhật các thông tin tuyển dụng mới nhất từ các doanh nghiệp. Người lao động có thể tìm kiếm công việc phù hợp theo ngành nghề, vị trí và yêu cầu tuyển dụng. ', '2026-08-30 18:15:05', 'ac73ea858411ffe67e0213f0f1c3abd9', 1, 1, 1, '*', '2026-08-30 18:13:35', NULL, '2026-08-30 18:13:35', NULL, 0, 0, 3, );
INSERT INTO `tu9j5_finder_links` (`link_id`, `url`, `route`, `title`, `description`, `indexdate`, `md5sum`, `published`, `state`, `access`, `language`, `publish_start_date`, `publish_end_date`, `start_date`, `end_date`, `list_price`, `sale_price`, `type_id`, `object`) VALUES
(18, 'index.php?option=com_content&view=article&id=9', 'index.php?option=com_content&view=article&id=9:cong-ty-tnhh-k-thu-t-tien-phong&catid=10', 'Công ty TNHH Kỹ Thuật Tiên Phong ', ' Công ty TNHH Kỹ Thuật Tiên Phong Cần tuyển 1 vị trí Lĩnh vực: Dịch vụ và thương mại Địa điểm: 437/33 Hoàng Văn Thụ, Phường Tân Sơn Nhất, Thành phố Hồ Chí Minh Nhu cầu tuyển dụng: Nhân viên Văn phòng, Kinh doanh Quyền lợi: Môi trường làm việc chuyên nghiệp, thu nhập ổn định và có cơ hội phát triển. Điện thoại: 0900000000 Email: Thời hạn nộp hồ sơ: 01/09/2026-05/09/2026 ', '2026-08-30 18:53:21', 'f5234aba630558a7db825f87d415e393', 1, 1, 1, '*', '2026-08-30 18:53:21', NULL, '2026-08-30 18:53:21', NULL, 0, 0, 3, ),
(19, 'index.php?option=com_content&view=article&id=10', 'index.php?option=com_content&view=article&id=10:cong-ty-tnhh-new-zealand-infinite-power&catid=10', 'CÔNG TY TNHH NEW ZEALAND INFINITE POWER', ' CÔNG TY TNHH NEW ZEALAND INFINITE POWER 174 - Giám đốc, Phó Giám đốc công ty, doanh nghiệp, xí nghiệp, hợp tác xã; Hiệu trưởng, Phó Hiệu trưởng trường nhỏ và tương đương (chuyên trách) Khu vực tuyển: Thành phố Hồ Chí Minh Hạn nộp hồ sơ: 26/08/2026 Mức lương: 35 ~ 50 triệu Địa điểm làm việc 1. Số 16, đường số 07, khu dân cư Himlam, Phường Long Hương, Thành phố Hồ Chí Minh Mô tả công việc + Định hướng, xây dựng và thực thi chiến lược thương hiệu, quảng bá và nghiên cứu thị trường công nghệ để thúc đẩy doanh thu và đem lại lợi nhuận cao nhất; + Hoạch định chiến lược, Quản lý thương hiệu, Nghiên cứu thị trường, Triển khai & Kiểm soát: Kiểm duyệt kế hoạch, tổ chức sự kiện và quản lý ngân sách marketing để tối ưu hóa hiệu quả (KPIs); + Chịu trách nhiệm quản lý, điều hành, chỉ đạo đội ngũ nhân lực tại phòng kinh doanh nhằm đảm bảo hoàn thành đạt chỉ tiêu tất cả các hoạt động liên quan đến mua bán, cho thuê, quản lý bất động sản, cũng như phát triển chiến lược kinh doanh và đạt được các mục tiêu doanh số; +Quản lý, giám sát nhân viên trực thuộc, chọn lọc, huấn luyện và đào tạo nhân viên. Xây dựng môi trường làm việc linh hoạt và chuyên nghiệp, khuyến khích nhân viên làm việc tích cực để đạt hiệu quả cao trong công việc Yêu cầu công việc • Có kinh nghiệm dày dặn trong việc quản lý và đáp ứng các điều kiện được bổ nhiệm phù hợp với quy định của công ty đặt ra với vị trí Giám đốc. Khả năng sắp xếp, phân tích công việc tốt, nhanh nhạy trong nắm bắt, giải quyết vấn đề. • Chịu được áp lực doanh số cao • Ưu tiên lao động có sẵn mối quan hệ với các khách hàng và đối tác trong cùng lĩnh vực Quyền lợi theo quy định của nhà nước Việt Nam ', '2026-08-30 18:55:58', '3d35b84cd618a7627374d3afd14a9ae5', 1, 1, 1, '*', '2026-08-30 18:55:58', NULL, '2026-08-30 18:55:58', NULL, 0, 0, 3, ),
(20, 'index.php?option=com_contact&view=contact&id=1', 'index.php?option=com_contact&view=contact&id=1:trung-tam-gi-i-thi-u-vi-c-lam&catid=4:uncategorised', 'Trung tâm giới thiệu việc làm', '', '2026-08-30 19:22:40', 'b29b51dd89a6fed8c6cd7e51920de4b6', 1, 1, 1, '*', NULL, NULL, '2026-08-30 19:22:40', NULL, 0, 0, 2, );

